<template><div class="s1-detail"><template v-for="(item,key) in value"><div v-if="item!==null&&item!==undefined" :key="key" class="s1-detail-row"><strong>{{names[key]||key}}</strong><div v-if="isFiles(key,item)"><Button v-for="id in item" :key="id" size="small" @click="$emit('preview',id)">预览附件 {{id}}</Button></div><RecordDetail v-else-if="item&&typeof item==='object'&&!Array.isArray(item)" :value="item" @preview="$emit('preview',$event)"/><div v-else-if="Array.isArray(item)"><span v-if="!item.length">无</span><template v-for="(entry,index) in item"><RecordDetail v-if="entry&&typeof entry==='object'" :key="index" :value="entry" @preview="$emit('preview',$event)"/><Tag v-else :key="index">{{key==='incompleteFields'?(names[entry]||entry):label(entry)}}</Tag></template></div><span v-else>{{typeof item==='boolean'?(item?'是':'否'):label(item)}}</span></div></template></div></template>
<script>import {label} from './shared';export default {name:'RecordDetail',props:{value:{type:Object,default:()=>({})}},data:()=>({names:{impact:'当前影响范围',storeTotal:'影响店铺数',goodsTotal:'影响商品数',stores:'当前店铺',policyVersion:'类目策略版本',pageNumber:'当前页',pageSize:'每页记录数',id:'编号',storeId:'店铺编号',name:'名称',storeName:'店铺名称',kind:'申请类型',status:'状态',state:'状态',version:'数据版本',revision:'提交版本',payload:'申请内容',history:'历史记录',store:'店铺',profile:'商户资料',subjectType:'主体类型',legalName:'主体名称',legalPerson:'法定代表人',legalCode:'统一社会信用代码',contactName:'联系人',phone:'联系电话',provinceCode:'省编码',cityCode:'市编码',districtCode:'区县编码',address:'详细地址',businessHours:'营业时间',description:'介绍',categoryIds:'类目范围',qualifications:'资质',type:'类型',scope:'适用范围',validFrom:'有效期开始',validTo:'有效期结束',longTerm:'长期有效',details:'详细信息',galleryFileIds:'商品图片',fileIds:'附件',licenseNumber:'证照编号',reason:'原因',reviewedAt:'审核时间',submittedAt:'提交时间',approvedAt:'批准时间',updatedAt:'更新时间',createdAt:'创建时间',versions:'版本历史',drafts:'待审资料',warning:'到期提示',revocationReason:'撤销原因',closedReason:'关闭原因',admissionState:'准入状态',extra:'结构化信息',number:'协议编号',agreementId:'关联协议',agreementRevision:'协议版本',ruleKey:'规则编号',businessType:'业务',platformLegalName:'平台主体',merchantLegalName:'商户主体',merchantLegalCode:'商户主体代码',startDate:'开始日期（上海时区）',endDate:'结束日期（含当日）',confirmationReference:'确认凭据',rateBps:'佣金比例（万分比）',baseCode:'计费基数',roundCode:'取整方式',commissionClause:'佣金条款',refundSummary:'退款规则摘要',triggerBasis:'触发依据',executionIntent:'执行意图',note:'备注',actualFrom:'实际生效开始',actualTo:'实际生效截止（不含）',confirmedAt:'确认时间',publishedAt:'发布时间',terminatedAt:'终止时间',disabledAt:'停用时间',replacedAt:'续约截断时间',predecessorId:'前序版本',goods:'商品',skus:'规格库存',reviews:'审核历史',regulationHistory:'监管历史',content:'内容快照',contentVersion:'内容版本',approvedVersion:'批准内容版本',reviewStatus:'审核状态',marketStatus:'销售状态',forcedOff:'强制下架',forcedReason:'监管原因',quantity:'可售数量',priceCent:'价格（分）',costCent:'成本（分）',costVersion:'成本版本',inventoryVersion:'库存版本',weightGram:'重量（克）',enabled:'已启用',methods:'配置方式',effectiveMethods:'有效方式',specifications:'规格组合',code:'编码',submittedOnce:'已进入审核',decision:'审核决定',submitted:'送审快照',mode:'渠道模式',configId:'配置编号',displayName:'名称',receiver:'平台接收关系',operations:'操作历史',action:'动作',failureCode:'失败原因',trustSource:'核验来源',verifiedAt:'核验时间',completedAt:'完成时间',materialRevision:'材料版本',application:'进件',relation:'二级商户关系',configuration:'配置',fixedFeeCent:'固定运费（分）',districtCodes:'配送区县',points:'点位',pointType:'点位类型',complete:'资料完整',incompleteFields:'待补字段',region:'行政区划',opening:'开放时间',days:'星期',from:'开始',to:'结束',latitude:'纬度',longitude:'经度',contact:'联系人',configVersion:'配置版本',maxRatioBps:'渠道比例上限（万分比）'}}),methods:{label,isFiles(key,value){return ['fileIds','attachmentIds','galleryFileIds'].includes(key)&&Array.isArray(value);}}};</script>
<style scoped>.s1-detail{border-left:2px solid #e8eaec;padding:2px 12px;margin:8px 0}.s1-detail-row{display:flex;align-items:flex-start;gap:16px;padding:6px 0;overflow-wrap:anywhere}.s1-detail-row>strong{flex:0 0 155px;color:#515a6e}.s1-detail-row>div{flex:1;min-width:0}.s1-detail button{margin:0 8px 8px 0}</style>
